def strange_sort_list(lst):
    if not lst:
        return []

    result = []
    lst_sorted = sorted(lst)

    while lst_sorted:
        result.append(lst_sorted.pop(0))  # Add the minimum
        if lst_sorted:
            result.append(lst_sorted.pop(-1))  # Add the maximum

    return result
